using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;
public class GWFlightProfile{public string Name,Body,Altitude,Inclination;public bool Stage,Warp;}
public class GWSurfaceSite{public string Name,Body;public double Latitude,Longitude,Height;}
public static class GroundworksNavigation{
 public static double Distance(double radius,double lat1,double lon1,double lat2,double lon2){double r=Math.PI/180,a=lat1*r,b=lat2*r,d=(lon2-lon1)*r;double cosine=Math.Sin(a)*Math.Sin(b)+Math.Cos(a)*Math.Cos(b)*Math.Cos(d);return radius*Math.Acos(Math.Max(-1,Math.Min(1,cosine)));}
 public static double Bearing(double lat1,double lon1,double lat2,double lon2){double r=Math.PI/180,a=lat1*r,b=lat2*r,d=(lon2-lon1)*r;double angle=Math.Atan2(Math.Sin(d)*Math.Cos(b),Math.Cos(a)*Math.Sin(b)-Math.Sin(a)*Math.Cos(b)*Math.Cos(d))/r;return (angle+360)%360;}
 public static double Slope(double north,double south,double east,double west,double spacing){return Math.Atan(Math.Sqrt(Math.Pow((north-south)/(2*spacing),2)+Math.Pow((east-west)/(2*spacing),2)))*180/Math.PI;}
}
public class GroundworksFlightTools{
 public readonly List<GWFlightProfile> Profiles=new List<GWFlightProfile>();public readonly List<GWSurfaceSite> Sites=new List<GWSurfaceSite>();public readonly List<string> History=new List<string>();public int LastProfileIndex,LastSiteIndex;public string LastError="";public readonly string Folder;
 public GroundworksFlightTools(string folder){Folder=folder;Load();}
 string Settings{get{return Path.Combine(Folder,"flight-tools.cfg");}}string Journal{get{return Path.Combine(Folder,"flight-events.log");}}
 static string Clean(string value){if(value==null)return "";string s=new string(value.Where(c=>!char.IsControl(c)&&c!='{'&&c!='}'&&c!='/'&&c!='\\').ToArray()).Trim();return s.Length>32?s.Substring(0,32):s;}
 static bool Number(string s,out double value){return double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out value)&&GroundworksGuidanceMath.Finite(value);}static string Num(double value){return value.ToString("R",CultureInfo.InvariantCulture);}
 public void Load(){Profiles.Clear();Sites.Clear();History.Clear();try{if(File.Exists(Settings)){var root=ConfigNode.Load(Settings);var n=root.GetNode("GROUNDWORKS_FLIGHT_TOOLS")??root;foreach(var p in n.GetNodes("PROFILE")){double altitude,inc;bool stage,warp;if(Profiles.Count>=32||!Number(p.GetValue("altitude"),out altitude)||altitude<=0||!Number(p.GetValue("inclination"),out inc)||Math.Abs(inc)>180)continue;Profiles.Add(new GWFlightProfile{Name=Clean(p.GetValue("name")),Body=p.GetValue("body")??"",Altitude=p.GetValue("altitude"),Inclination=p.GetValue("inclination"),Stage=bool.TryParse(p.GetValue("stage"),out stage)&&stage,Warp=bool.TryParse(p.GetValue("warp"),out warp)&&warp});}foreach(var p in n.GetNodes("SITE")){double lat,lon,height;if(Sites.Count>=64||!Number(p.GetValue("latitude"),out lat)||Math.Abs(lat)>90||!Number(p.GetValue("longitude"),out lon)||!Number(p.GetValue("height"),out height))continue;Sites.Add(new GWSurfaceSite{Name=Clean(p.GetValue("name")),Body=p.GetValue("body")??"",Latitude=lat,Longitude=lon,Height=height});}}if(File.Exists(Journal)){var all=File.ReadAllLines(Journal);History.AddRange(all.Skip(Math.Max(0,all.Length-256)));}}catch(Exception e){LastError=e.Message;}}
 bool Save(){try{var n=new ConfigNode("GROUNDWORKS_FLIGHT_TOOLS");n.AddValue("version",1);foreach(var p in Profiles){var c=n.AddNode("PROFILE");c.AddValue("name",p.Name);c.AddValue("body",p.Body);c.AddValue("altitude",p.Altitude);c.AddValue("inclination",p.Inclination);c.AddValue("stage",p.Stage);c.AddValue("warp",p.Warp);}foreach(var p in Sites){var c=n.AddNode("SITE");c.AddValue("name",p.Name);c.AddValue("body",p.Body);c.AddValue("latitude",Num(p.Latitude));c.AddValue("longitude",Num(p.Longitude));c.AddValue("height",Num(p.Height));}Directory.CreateDirectory(Folder);n.Save(Settings);LastError="";return true;}catch(Exception e){LastError=e.Message;return false;}}
 public bool SaveProfile(string name,string body,string altitude,string inclination,bool stage,bool warp){double a,i;name=Clean(name);if(name.Length==0||!Number(altitude,out a)||a<=0||!Number(inclination,out i)||Math.Abs(i)>180){LastError="Enter a name and valid orbit values";return false;}var p=Profiles.FirstOrDefault(x=>x.Name==name&&x.Body==body);if(p==null){if(Profiles.Count>=32){LastError="Profile limit reached";return false;}p=new GWFlightProfile();Profiles.Add(p);}p.Name=name;p.Body=body;p.Altitude=Num(a);p.Inclination=Num(i);p.Stage=stage;p.Warp=warp;LastProfileIndex=Profiles.IndexOf(p);return Save();}
 public bool SaveSite(string name,string body,double latitude,double longitude,double height){name=Clean(name);if(name.Length==0||!GroundworksGuidanceMath.Finite(latitude)||Math.Abs(latitude)>90||!GroundworksGuidanceMath.Finite(longitude)||!GroundworksGuidanceMath.Finite(height)){LastError="Enter a site name and valid coordinates";return false;}var p=Sites.FirstOrDefault(x=>x.Name==name&&x.Body==body);if(p==null){if(Sites.Count>=64){LastError="Site limit reached";return false;}p=new GWSurfaceSite();Sites.Add(p);}p.Name=name;p.Body=body;p.Latitude=latitude;p.Longitude=((longitude+180)%360+360)%360-180;p.Height=height;LastSiteIndex=Sites.IndexOf(p);return Save();}
 public bool RemoveSite(int index){if(index<0||index>=Sites.Count)return false;Sites.RemoveAt(index);return Save();}
 public void Record(double ut,string body,string vessel,string action){try{string entry=ut.ToString("F1",CultureInfo.InvariantCulture)+" s | "+Clean(body)+" | "+Clean(vessel)+" | "+action.Replace('\n',' ').Replace('\r',' ');History.Add(entry);if(History.Count>256)History.RemoveRange(0,History.Count-256);Directory.CreateDirectory(Folder);File.WriteAllLines(Journal,History.ToArray());}catch(Exception e){LastError=e.Message;}}
 public string Export(string gameRoot){string folder=Path.Combine(gameRoot,"Groundworks-Logs");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"flight-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+".txt");File.WriteAllLines(file,History.ToArray());return file;}
}
